-- Run only in the isolated profile generated by stage_port.py. No synth/hardware.
local profile=reaper.GetResourcePath()
local root=assert(profile:match('^(/tmp/chordlab%-.+)/reaper$'),'Scratch /tmp/chordlab-* profile only')
local marker=assert(io.open(root..'/manifest.json'));marker:close()
local _,project=reaper.EnumProjects(-1,'')
assert(project==root..'/prototype.rpp','Open the generated prototype.rpp first')
assert(reaper.CountTracks(0)==0,'Refusing to replace existing tracks')
reaper.OnStopButton()
reaper.gmem_attach('ChordLab_AB_Prototype')
for i=0,51001 do reaper.gmem_write(i,0) end

local function setup(lane)
  reaper.InsertTrackAtIndex(lane,false)
  local t=reaper.GetTrack(0,lane)
  if lane==0 then
    assert(reaper.TrackFX_AddByName(t,'ChordLab/chordlab.jsfx',false,-1)==0)
    reaper.TrackFX_SetParam(t,0,13,1)
    reaper.GetSetMediaTrackInfo_String(t,'P_NAME','A - native JSFX',true)
  else
    local f=assert(io.open(root..'/wrapper-track.txt'))
    local chunk=f:read('*a');f:close()
    assert(reaper.SetTrackStateChunk(t,chunk,false))
    local ok,name=reaper.TrackFX_GetFXName(t,0)
    assert(ok and (name:find('ysfx%-s FX') or name:find('Chord Lab')),'CLAP not loaded')
  end
  assert(reaper.TrackFX_AddByName(t,'ChordLab/ab_source.jsfx',false,-1)==1)
  reaper.TrackFX_CopyToTrack(t,1,t,0,true)
  reaper.TrackFX_SetParam(t,0,0,lane)
  assert(reaper.TrackFX_AddByName(t,'ChordLab/ab_capture.jsfx',false,-1)==2)
  reaper.TrackFX_SetParam(t,2,0,lane)
  reaper.SetMediaTrackInfo_Value(t,'B_MAINSEND',1)
  reaper.SetMediaTrackInfo_Value(t,'I_RECINPUT',4096+62*32) -- VKB only, no hardware
  reaper.SetMediaTrackInfo_Value(t,'I_RECARM',1)
  reaper.SetMediaTrackInfo_Value(t,'I_PERFFLAGS',3)
  reaper.SetTrackUIInputMonitor(t,1,0)
  return t
end
local tracks={setup(0),setup(1)}
local cases={}
local function add(label,events,min_events)
  cases[#cases+1]={label=label,events=events,min_events=min_events or 0}
end
local function tap(label,n,min_events)
  add(label,{{0,0x9f,n,100},{1,0x8f,n,0}},min_events)
end
for key=0,11 do
  tap('key '..key,60+key)
  for degree=0,6 do
    local prefix=key..'/'..degree
    add(prefix..' hold',{{13,0x9f,72+degree,100}},4)
    -- Seventh -> ninth -> triad -> seventh. Every inversion of each kind.
    for _,count in ipairs({4,5,3}) do
      for inv=1,count do tap(prefix..'/'..count..' L'..inv,80,6) end
      tap(prefix..'/'..count..' K',79,6)
      tap(prefix..'/'..count..' reset',81,6)
      tap(prefix..'/'..count..' Tab',85,6)
    end
    add(prefix..' release',{{63,0x8f,72+degree,0}},4)
    add(prefix..' recall',{{127,0x9f,72+degree,100}},4)
    add(prefix..' release recalled',{{255,0x8f,72+degree,0}},4)
  end
end
for _,ch in ipairs({0,14}) do
  for velocity=1,127 do
    add('velocity '..ch..'/'..velocity,
        {{13,0x90+ch,60,velocity},{64,0x80+ch,60,0}},2)
  end
end
add('program change',{{11,0xc0,7,0},{137,0xce,127,0}},2)
add('poly pressure',{{15,0xa0,60,73},{199,0xae,72,101}},2)
add('zero velocity off',{{1,0x90,61,73},{65,0x90,61,0}},2)
add('pitchbend CC pressure',{{7,0xe0,3,65},{9,0xb0,1,91},{65,0xd0,45,0}},3)
tap('sustain ON',82)
add('pedal release while locked',{{17,0xb0,64,0},{129,0xbe,64,0}},2)
tap('sustain OFF',82)
add('pedal unlocked',{{13,0xb0,64,127},{193,0xb0,64,0}},2)
add('overlapping degrees',{{0,0x9f,74,100},{64,0x9f,75,100}},12)
add('return to previous degree',{{64,0x8f,75,0}},8)
add('release last degree',{{64,0x8f,74,0}},4)
add('duplicate hardware note ownership',{{0,0x90,60,100},{32,0x90,60,70},
    {64,0x80,60,0},{192,0x80,60,0}},2)
add('panic',{{0,0xbf,123,0},{1,0xb0,123,0}},1)

local function capture(lane)
  local base=1000+lane*50000
  assert(reaper.gmem_read(base+1)==0,'Capture overflow')
  local result={}
  for i=0,reaper.gmem_read(base)-1 do
    local p=base+2+i*4
    result[#result+1]=string.format('%d:%02x:%d:%d',reaper.gmem_read(p),
      reaper.gmem_read(p+1),reaper.gmem_read(p+2),reaper.gmem_read(p+3))
  end
  return result
end

local logs=assert(io.open(root..'/ab-events.tsv','w'))
logs:write('case\tlabel\tJSFX\tCLAP\n')
local index,failed,passed=0,0,0
local deadline=reaper.time_precise()+1
local function send(case)
  reaper.gmem_write(1,#case.events)
  for i,event in ipairs(case.events) do
    for j,v in ipairs(event) do reaper.gmem_write(30+(i-1)*4+j-1,v) end
  end
  reaper.gmem_write(0,index)
end

local function finish(error_message)
  logs:close()
  reaper.gmem_write(1,1)
  for j,v in ipairs({0,0xbf,123,0}) do reaper.gmem_write(29+j,v) end
  reaper.gmem_write(0,#cases+1)
  local f=assert(io.open(root..'/ab-result.txt','w'))
  f:write('cases=',#cases,'\npassed=',passed,'\nfailed=',failed,'\n')
  f:write('scope=ordered MIDI bytes and block-relative sample offsets; no GUI/state certification\n')
  if error_message then f:write('ERROR=',error_message,'\n') end
  f:close()
  reaper.Main_SaveProject(0,false)
  reaper.TrackFX_Show(tracks[2],1,3)
end

local function tick()
  if reaper.time_precise()<deadline then reaper.defer(tick);return end
  if index>0 then
    local case=cases[index]
    local a,b=capture(0),capture(1)
    local aa,bb=table.concat(a,','),table.concat(b,',')
    local ready=reaper.gmem_read(10)==index and reaper.gmem_read(11)==index
    local equal=ready and aa==bb and #a>=case.min_events
    if equal then passed=passed+1 else failed=failed+1 end
    logs:write(index,'\t',case.label,'\t',aa,'\t',bb,'\n')
  end
  index=index+1
  if index>#cases then finish();return end
  send(cases[index]);deadline=reaper.time_precise()+.08
  reaper.defer(function()
    local ok,err=pcall(tick)
    if not ok then finish(tostring(err)) end
  end)
end
reaper.defer(tick)
